import { Injectable } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { IsNull, type Repository } from "typeorm";
import { EntityRepository, type IUpdatableRepository } from "#/database/base/entity-repository.ts";
import { CountryEntity } from "#/modules/reference/schema/entities/country.entity.ts";
import * as Country from "#/modules/reference/schema/types/country/index.ts";

/**
 * Repository of Country: the base repository configured with the entity's
 * generated query fields. Regenerated by Dryv; the feature repositories build the contract's
 * named queries on top of it.
 */
@Injectable()
export class CountryRepository
  extends EntityRepository<
    CountryEntity,
    Country.Types.CountrySortableField,
    Country.Types.CountryEditableField,
    Country.Types.CountrySelectableField,
    Country.Types.ICountryCreatable
  >
  implements IUpdatableRepository<CountryEntity, Country.Types.ICountryUpdatable>
{
  constructor(
    @InjectRepository(CountryEntity)
    repository: Repository<CountryEntity>,
  ) {
    super(repository, Country.Config.COUNTRY_QUERY_OPTIONS);
  }

  /** Updates a row from only the editable fields of `data`. */
  async updateEditable(
    id: string,
    data: Country.Types.ICountryUpdatable,
  ): Promise<CountryEntity | null> {
    const stamped = await this.stampUpdate(id, data);
    return stamped === null ? null : await this.update(id, stamped);
  }

  /** Find the country with this code (unique). */
  async findByCode(code: NonNullable<CountryEntity["code"]>): Promise<CountryEntity | null> {
    return await this.findOne({ code, deletedAt: IsNull() });
  }
}
